import json
import os
import sys
import unittest
from datetime import datetime, timedelta, timezone

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

from fleet_lighthouse.core import (
    GhError, RepoVitals, collect, digest, diff_snapshots, list_org_repos,
)


def make_runner(responses):
    """responses: list of (argv_substring, stdout) or (substring, GhError)."""
    def runner(argv):
        joined = " ".join(argv)
        for key, out in responses:
            if key in joined:
                if isinstance(out, Exception):
                    raise out
                return out
        raise GhError(f"no canned response for: {joined}")
    return runner


FRESH_PUSH = (datetime.now(timezone.utc) - timedelta(days=1)).strftime("%Y-%m-%dT%H:%M:%SZ")
STALE_PUSH = (datetime.now(timezone.utc) - timedelta(days=30)).strftime("%Y-%m-%dT%H:%M:%SZ")


class TestCollect(unittest.TestCase):
    def test_happy_path(self):
        r = make_runner([
            ("repo view", json.dumps({"pushedAt": FRESH_PUSH, "branch": "main", "issues": 3})),
            ("pr list", "2\n"),
            ("run list", "0\n"),
            ("api repos/SuperInstance/x/pages", json.dumps({"status": "built"})),
        ])
        v = collect(["x"], "SuperInstance", r)[0]
        self.assertEqual(v.name, "SuperInstance/x")
        self.assertEqual(v.open_prs, 2)
        self.assertEqual(v.failing_runs, 0)
        self.assertEqual(v.pages_status, "built")
        self.assertEqual(v.default_branch, "main")
        self.assertLess(v.staleness_days, 2)

    def test_repo_view_error_marks_vitals(self):
        r = make_runner([("repo view", GhError("404"))])
        v = collect(["ghost"], "SuperInstance", r)[0]
        self.assertIn("404", v.error)

    def test_optional_fields_tolerate_failure(self):
        r = make_runner([
            ("repo view", json.dumps({"pushedAt": FRESH_PUSH, "branch": "main", "issues": 0})),
            ("pr list", GhError("auth")),
            ("run list", GhError("auth")),
            ("api repos/SuperInstance/x/pages", GhError("404 Not Found")),
        ])
        v = collect(["x"], "SuperInstance", r)[0]
        self.assertEqual(v.error, "")
        self.assertEqual(v.open_prs, -1)
        self.assertEqual(v.pages_status, "none")

    def test_org_listing(self):
        r = make_runner([("repo list", "quilt-studio\ntwist-engine\n")])
        self.assertEqual(list_org_repos("SuperInstance", r), ["quilt-studio", "twist-engine"])


    def test_failing_run_window_passed_to_gh(self):
        seen = {}
        def spy(argv):
            joined = " ".join(argv)
            if "run list" in joined:
                seen["argv"] = joined
                return "3\n"
            return make_runner([
                ("repo view", json.dumps({"pushedAt": FRESH_PUSH, "branch": "main", "issues": 0})),
                ("pr list", "0\n"), ("api repos/", GhError("404")),
            ])(argv)
        v = collect(["x"], "SuperInstance", spy, fail_window_days=7)[0]
        self.assertEqual(v.failing_runs, 3)
        self.assertIn("--created", seen["argv"])
        self.assertIn("--status failure", seen["argv"])


class TestDigest(unittest.TestCase):
    def _v(self, **kw):
        base = dict(name="o/r", pushed_at=FRESH_PUSH, open_prs=0, open_issues=0,
                    failing_runs=0, pages_status="built", default_branch="main", error="")
        base.update(kw)
        return RepoVitals(**{k: base[k] for k in RepoVitals.__dataclass_fields__})

    def test_healthy(self):
        d = digest([self._v()])
        self.assertEqual((d["healthy"], d["total"]), (1, 1))
        self.assertEqual(d["rows"][0]["problems"], [])

    def test_stale_flagged(self):
        d = digest([self._v(pushed_at=STALE_PUSH)], stale_days=14)
        self.assertTrue(any("stale" in p for p in d["rows"][0]["problems"]))

    def test_failing_runs_flagged(self):
        d = digest([self._v(failing_runs=2)])
        self.assertTrue(any("failing" in p for p in d["rows"][0]["problems"]))

    def test_pages_errored(self):
        d = digest([self._v(pages_status="errored")])
        self.assertTrue(any("pages" in p for p in d["rows"][0]["problems"]))

    def test_error_flagged(self):
        d = digest([self._v(error="boom")])
        self.assertTrue(any("collect-error" in p for p in d["rows"][0]["problems"]))


class TestDiff(unittest.TestCase):
    def _d(self, rows):
        return {"healthy": sum(1 for r in rows if not r["problems"]),
                "total": len(rows), "rows": rows}

    def _row(self, name, problems, prs=0):
        return {"name": name, "staleness_days": 1, "open_prs": prs,
                "failing_runs": 0, "open_issues": 0, "pages_status": "built",
                "error": "", "problems": problems}

    def test_new_problem(self):
        old = self._d([self._row("a", [])])
        new = self._d([self._row("a", ["stale 30d"])])
        changes = diff_snapshots(old, new)
        self.assertEqual(len(changes), 1)
        self.assertIn("🔴", changes[0])
        self.assertIn("NEW stale 30d", changes[0])

    def test_cleared_problem(self):
        old = self._d([self._row("a", ["stale 30d"])])
        new = self._d([self._row("a", [])])
        self.assertTrue(any("🟢" in c and "cleared" in c for c in diff_snapshots(old, new)))

    def test_new_and_removed_repos(self):
        old = self._d([self._row("a", [])])
        new = self._d([self._row("b", [])])
        changes = diff_snapshots(old, new)
        self.assertTrue(any(c.startswith("+ b") for c in changes))
        self.assertTrue(any(c.startswith("− a") for c in changes))

    def test_pr_count_change(self):
        old = self._d([self._row("a", [], prs=1)])
        new = self._d([self._row("a", [], prs=4)])
        self.assertTrue(any("PRs 1 → 4" in c for c in diff_snapshots(old, new)))

    def test_no_changes(self):
        d = self._d([self._row("a", [])])
        self.assertEqual(diff_snapshots(d, d), [])


class TestCLI(unittest.TestCase):
    def setUp(self):
        self.runner = make_runner([
            ("repo view", json.dumps({"pushedAt": FRESH_PUSH, "branch": "main", "issues": 0})),
            ("pr list", "0\n"), ("run list", "0\n"),
            ("api repos/", GhError("404")),
        ])
        import fleet_lighthouse.cli as cli
        self._old_cache = cli.CACHE
        import tempfile
        cli.CACHE = os.path.join(tempfile.mkdtemp(), "last.json")
        self.cli = cli

    def tearDown(self):
        self.cli.CACHE = self._old_cache

    def _argv(self, *extra):
        return ["report", "--repos", "x", "--org", "SuperInstance", *extra]

    def test_report_exit_0_healthy(self):
        self.assertEqual(self.cli.main(self._argv(), runner=self.runner), 0)

    def test_report_json(self):
        self.assertEqual(self.cli.main(self._argv("--format", "json"), runner=self.runner), 0)

    def test_fail_on_unhealthy(self):
        bad = make_runner([
            ("repo view", json.dumps({"pushedAt": STALE_PUSH, "branch": "main", "issues": 9})),
            ("pr list", "0\n"), ("run list", "0\n"), ("api repos/", GhError("404")),
        ])
        rc = self.cli.main(self._argv("--fail-on-unhealthy"), runner=bad)
        self.assertEqual(rc, 1)

    def test_since_last_two_runs(self):
        self.cli.main(self._argv("--since-last"), runner=self.runner)
        self.assertTrue(os.path.exists(self.cli.CACHE))
        self.assertEqual(self.cli.main(self._argv("--since-last"), runner=self.runner), 0)

    def test_watch_rounds(self):
        self.assertEqual(
            self.cli.main(["watch", "--repos", "x", "--interval", "1", "--rounds", "2"],
                          runner=self.runner), 0)


if __name__ == "__main__":
    unittest.main()
